    def test_split_pairs(self):
        self.assertEqual(split_pairs("a=1,b=2"), [("a", "1"), ("b", "2")])

    def test_mean(self):
        self.assertEqual(mean([2, 4, 6]), 4)

    def test_slug(self):
        self.assertEqual(slug("Hello World"), "hello-world")


